<div class="page-heading d-flex justify-content-between align-items-end flex-wrap gap-3"><div><p class="eyebrow">Access control</p><h1>User Management</h1><p>Assign least-privilege roles and manage account status.</p></div><a class="btn btn-primary" href="/admin/users/create"><i class="bi bi-person-plus"></i> New user</a></div><?php require base_path('views/admin/_nav.php'); ?><div class="panel"><div class="table-responsive"><table class="table admin-table align-middle"><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Last login</th><th><span class="visually-hidden">Actions</span></th></tr></thead><tbody><?php foreach($users as $item):?><tr><td><strong><?=e($item['name'])?></strong><small><?=e($item['email'])?></small></td><td><?=e($item['role_name'])?></td><td><span class="badge <?=$item['is_active']?'text-bg-success':'text-bg-secondary'?>"><?=$item['is_active']?'Active':'Inactive'?></span></td><td><?=$item['last_login_at']?date('M j, Y H:i',strtotime($item['last_login_at'])):'Never'?></td><td><a class="btn btn-sm btn-outline-primary" href="/admin/users/<?=$item['id']?>/edit" title="Edit user"><i class="bi bi-pencil"></i></a></td></tr><?php endforeach;?></tbody></table></div></div>
